-- ============================================================================
-- database/seeds/standard_positions.sql
--
-- 标准岗位 seed（20 个岗位，覆盖主要部门）
--
-- 命名规范：
--   name     = 中文（项目默认语言）
--   name_en  = 英文（多语言对照）
--   code     = 岗位编码
--   level    = 职级（1=基层，2=主管，3=经理，4=总监，5=高管）
--
-- 前置依赖：standard_departments.sql 必须先执行
--
-- 用法：
--   psql -U topems_prod -d topems_prod -f database/seeds/standard_positions.sql
-- ============================================================================

-- ── 高管层（level=5）──

-- ── 人力资源部（level=3/2/1）──

-- ── 财务部（level=3/2/1）──

-- ── 信息技术部（level=3/2/1）──

-- ── 销售市场部（level=3/2/1）──

-- ── 生产部（level=3/2/1）──

-- ── 质量管理部（level=3/2/1）──

-- ── 供应链部（level=3/2/1）──

-- 验证
SELECT count(*) AS total_positions FROM hrm.positions WHERE deleted_at IS NULL;
